<template>
    <div class="layout-px-spacing ">  
            <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;">Workshop</a></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>Dashboard</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>

 <teleport to="#breadcrumb">
              <div class="flex-row ms-auto me-5">
                <span v-html="refreshButton(getAssetServices,loading)"></span>
            </div>
 </teleport>


    <!-- Main Layout: Left Container (8 cols) and Right Container (4 cols) -->
    <div class="row g-2">
      <!-- Left Container: 8 columns -->
      <div class="col-md-8">
        <!-- Top Row: Summary and Notifications -->
        <div class="row g-2 mb-2">
      <!-- Summary Section -->
          <div class="col-md-6">
            <div class="card border-0 shadow-sm">
          <div class="card-header bg-white border-bottom">
            <h5 class="mb-0">
              <i class="fa fa-chart-bar me-2 text-primary"></i>Summary
            </h5>
          </div>
          <span v-if="loading" v-html="rowShimmer(3)">

          </span>
          <div v-else class="card-body">
            <div class="list-group list-group-flush">
              <a 
                href="#" 
                @click.prevent="navigateToJobCards" 
                class="list-group-item list-group-item-action d-flex justify-content-between align-items-center border-0 px-0"
              >
                <div class="d-flex align-items-center">
                  <i class="fa fa-wrench text-primary me-3"></i>
                  <span>Job Cards</span>
                </div>
                <span class="badge bg-primary rounded-pill">{{ services.jobcards || 0 }}</span>
              </a>
              <a 
                href="#" 
                @click.prevent="navigateToJobCards('closed')" 
                class="list-group-item list-group-item-action d-flex justify-content-between align-items-center border-0 px-0"
              >
                <div class="d-flex align-items-center">
                  <i class="fa fa-check-circle text-warning me-3"></i>
                  <span>Closed Job Cards</span>
                </div>
                <span class="badge bg-warning rounded-pill">{{ services.closed_jobcards || 0 }}</span>
              </a>
              <a 
                href="#" 
                @click.prevent="navigateToIncidents" 
                class="list-group-item list-group-item-action d-flex justify-content-between align-items-center border-0 px-0"
              >
                <div class="d-flex align-items-center">
                  <i class="fa fa-exclamation-triangle text-danger me-3"></i>
                  <span>Incidents Reported</span>
                </div>
                <span class="badge bg-danger rounded-pill">{{ services.incidents_reported || 0 }}</span>
              </a>
            </div>
          </div>
        </div>
      </div>

      <!-- Notifications Section -->
          <div class="col-md-6">
            <div class="card border-0 shadow-sm">
          <div class="card-header bg-white border-bottom">
            <h5 class="mb-0">
              <i class="fa fa-bell me-2 text-warning"></i>Notifications
            </h5>
          </div>
                     <span v-if="loading" v-html="rowShimmer(3)"></span>
          <div v-else class="card-body">
            <div class="list-group list-group-flush">
              <a 
                href="#" 
                @click.prevent="scrollToDueServices" 
                class="list-group-item list-group-item-action d-flex justify-content-between align-items-center border-0 px-0"
              >
                <div class="d-flex align-items-center">
                  <i class="fa fa-clock text-danger me-3"></i>
                  <span>Services Due</span>
                </div>
                <span class="badge bg-danger rounded-pill">{{ services.overdue || 0 }}</span>
              </a>
              <a 
                href="#" 
                class="list-group-item list-group-item-action d-flex justify-content-between align-items-center border-0 px-0"
              >
                <div class="d-flex align-items-center">
                  <i class="fa fa-exclamation-circle text-warning me-3"></i>
                  <span>Due Soon
                  </span>
                </div>
                <span class="badge bg-warning rounded-pill">{{ services.due_soon || 0 }}</span>
              </a>
              <a 
                href="#" 
                @click.prevent="navigateToInspections" 
                class="list-group-item list-group-item-action d-flex justify-content-between align-items-center border-0 px-0"
              >
                <div class="d-flex align-items-center">
                  <i class="fa fa-clipboard-check text-info me-3"></i>
                  <span>Pending Inspections</span>
                </div>
                <span class="badge bg-info rounded-pill">{{ services.pending_inspections || 0 }}</span>
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>

        <!-- Bottom: Vehicle Latest Service -->
        <div class="row g-2">
          <div class="col-12">
        <div class="card border-0 shadow-sm">
          <div class="card-header bg-white border-bottom d-flex justify-content-between align-items-center">
            <h5 class="mb-0">
              <i class="fa fa-history me-2 text-info"></i>Vehicle & Machines Latest Service
            </h5>
          </div>
          <div class="card-body">
            <span v-if="loading" v-html="tableShimmer()"></span>
                        <v-client-table v-else :data="jobcards" :columns="columns" :options="table_option" >
                          <template #status="props">
                                <span class="badge inv-status" :class="'badge-' + props.row.status.color">{{ props.row.status.name }}</span>
                            </template> 

                                                      <template #asset="props">
                                                        <router-link :to="`/asset/profile/${props.row.machine_id}`">
                                                               <span class="badge inv-status badge-dark" >{{ props.row.asset }}</span>
                                                        </router-link>
                            </template> 

                            <template #jobcard="props">
                                <router-link :to="`/jobcard/${props.row.jobcard}/${props.row.machine.id}`">
                                <span class="badge inv-status badge-primary" >{{ props.row.jobcard }}</span>
                             </router-link>
                            </template> 

                        </v-client-table>
        </div>
            </div>
          </div>
        </div>
      </div>

      <!-- Right Container: 4 columns - Due Services (Full height) -->
      <div class="col-md-4">
        <div class="card border-0 shadow-sm due-services-card">
          <div class="card-header bg-white border-bottom">
            <h5 class="mb-0">
              <i class="fa fa-list me-2 text-warning"></i>Due Services
              <span class="badge bg-warning ms-2">{{ services?.due_services }}</span>
            </h5>
          </div>
            <span v-if="loading" v-html="rowShimmer(20)"></span>
          <div v-else class="card-body due-services-body">
            <div v-if="dueServicesLoading" class="text-center py-4">
              <div class="spinner-border text-warning" role="status">
                <span class="visually-hidden">Loading...</span>
              </div>
            </div>
            <div v-else-if="services?.service-due?.length === 0" class="text-center py-4 text-muted">
              <i class="fa fa-check-circle fa-2x mb-2 text-success"></i>
              <p>No services due</p>
            </div>
            <div v-else>
              <div 
                v-for="(service, index) in services?.service_due" 
                :key="service.vehicle_id || index"
                class="border-bottom pb-3 mb-3 last:border-bottom-0"
              >
                <div class="d-flex justify-content-between align-items-start mb-2">
                  <div class="flex-grow-1">
                    <div class="fw-semibold text-truncate">{{ service.name || 'N/A' }}</div>
                    <div class="text-muted small">{{ service.service_name || service.last_service || 'N/A' }}</div>
                  </div>
                  <span class="badge " :class="getStatusBadgeClass(service.status)">
                    {{ service.status }}
                  </span>
                </div>
                <div class="small text-muted mb-2">
                  <div class="mb-1">
                    <i class="fa fa-tachometer-alt me-1"></i>Current: {{ formatNumber(service.latest_reading) }} {{ service.subject_unit }}
                  </div>
                  <div class="mb-1">
                    <i class="fa fa-flag me-1"></i>Due at: {{ formatNumber(service.due_at) }} {{ service.subject_unit }}
                  </div>
                  <div class="d-flex justify-content-between align-items-center">
                    <div v-if="service.overdue !== null && service.overdue !== undefined && service.overdue !== '-'" class="text-danger fw-semibold">
                      <i class="fa fa-exclamation-circle me-1"></i>Overdue: {{ formatNumber(service.overdue) }} {{ service.subject_unit }}
                    </div>
                    <div v-else-if="service.remaining !== null && service.remaining !== undefined && service.remaining !== '-'" class="text-warning fw-semibold">
                      <i class="fa fa-clock me-1"></i>Remaining: {{ formatNumber(service.due_at - service.latest_reading) }} {{ service.subject_unit }}
                    </div>
                    <div v-else class="flex-grow-1"></div>
                    <div class="ms-2 d-flex gap-1">
                      <button 
                        class="btn sm btn-primary"
                        @click="createJobCardFromService(service)"
                        title="Service Now - Create Job Card"
                        style="font-size: 0.7rem; padding: 2px 8px;"
                      >
                        <i class="fa fa-wrench me-1"></i> Service Now
                      </button>
                      <button 
                        v-if="service.job_card_id"
                        class="btn btn-xs btn-outline-primary"
                        @click="viewJobCardPDF(service)"
                        :title="'View Job Card PDF Report'"
                        style="font-size: 0.7rem; padding: 2px 8px;"
                      >
                        <i class="fa fa-file-pdf me-1"></i> View
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>






   </div>
</template>

<script setup>
    import { onMounted, ref,inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Workshop Dashboard' });

    const formatNumber = inject('formatNumber')
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const refreshButton = inject('refreshButton')
    const loading = ref('')
    const waitIndicator = inject('waitIndicator')
    const rowShimmer = inject('rowShimmer')
    const tableShimmer = inject('tableShimmer')

    const getStatusBadgeClass =(stat)=>{
      if(stat === 'due_soon'){
        return 'bg-warning'
      }else{
        return 'bg-danger'
      }
    }

    const columns = ref(['SNo', 'jobcard','asset','odometer','issuer','location', 'date', 'status']);
    const table_option = ref({
        perPage: 10,
        perPageValues: [10, 20, 50],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });


    const formatDate = inject('formatDate')

    const services = ref('')
    const jobcards = ref([])
    const getAssetServices = async ()  => {
        loading.value = true
        try{
          const response = await  axiosInstance.get('/asset-services')
          services.value = response.data
          jobcards.value = response.data.latest_jobcards.map((item,index)=>({
            ...item,
            SNo : index + 1,
            jobcard : item.id,
            asset : item.machine.name + ' - '+ item.machine.type_name,
            odometer : formatNumber(item.current_km_of_service),
            issuer : item.issuer.name,
            location : item.location.name,
            date : formatDate( item.created_at)
          }))
        }finally{
            loading.value = false
        }
    };






    onMounted(() => {
      getAssetServices()
    });
</script>

<style scoped>
.workshop-dashboard-page {
  padding: 0;
}

.card {
  transition: transform 0.2s;
}

.card:hover {
  transform: translateY(-2px);
}

.list-group-item {
  cursor: pointer;
  transition: background-color 0.2s;
}

.list-group-item:hover {
  background-color: #f8f9fa;
}

.sticky-top {
  position: sticky;
  z-index: 10;
}

/* Due Services Card - Auto height to fill screen */
.due-services-card {
  height: calc(100vh - 120px);
  min-height: 600px;
  display: flex;
  flex-direction: column;
}

.due-services-body {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
}

/* Custom scrollbar for service lists */
.card-body::-webkit-scrollbar,
.due-services-body::-webkit-scrollbar {
  width: 6px;
}

.card-body::-webkit-scrollbar-track,
.due-services-body::-webkit-scrollbar-track {
  background: #f1f1f1;
  border-radius: 10px;
}

.card-body::-webkit-scrollbar-thumb,
.due-services-body::-webkit-scrollbar-thumb {
  background: #888;
  border-radius: 10px;
}

.card-body::-webkit-scrollbar-thumb:hover,
.due-services-body::-webkit-scrollbar-thumb:hover {
  background: #555;
}
</style>


